-- Seed the 50 tracked companies from mockData.ts
-- This ensures the Supabase companies table has real data for subscribers.

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  sector = EXCLUDED.sector,
  country = EXCLUDED.country,
  country_code = EXCLUDED.country_code,
  cash_runway = EXCLUDED.cash_runway,
  insider_ownership = EXCLUDED.insider_ownership,
  scout_score = EXCLUDED.scout_score,
  next_catalyst = EXCLUDED.next_catalyst,
  catalyst_date = EXCLUDED.catalyst_date,
  institutional_flow = EXCLUDED.institutional_flow,
  market_cap = EXCLUDED.market_cap,
  description = EXCLUDED.description;